import re
from dataclasses import dataclass, field
from typing import Optional

# `## [2.4.0] - 2024-05-02` or `## [Unreleased]` (no date).
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?:\s*-\s*(?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Remove HTML comments (inline or multi-line) and any trailing whitespace they leave behind."""
    text = COMMENT.sub("", text)
    return "\n".join(line.rstrip() for line in text.splitlines())


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                # Not a release heading; ignore its content.
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def clean_body(lines):
    """Collapse runs of blank lines and drop leading/trailing blank lines."""
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] != "":
                out.append("")
        else:
            out.append(line)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            title = f"# {release.version} ({release.date})" if release.date else f"# {release.version}"
            body = clean_body(release.body)
            return f"{title}\n\n{body}\n"
    raise LookupError(version)

